function addOneBinary(s: string): string {
  // 100 -> 101
  // 1011 -> 1100
  // 11 -> 100
  const list = s.split('');
  if (list[list.length - 1] === '0') {
    list[list.length - 1] = '1';

    return list.join('');
  }

  let alreadyAdded = false;
  for (let i = list.length - 1; i >= 0; i--) {
    if (list[i] === '1') {
      list[i] = '0';
    } else {
      list[i] = '1';
      alreadyAdded = true;
      break;
    }
  }

  if (!alreadyAdded) {
    list.unshift('1');
  }

  return list.join('');
}

