export function maxProfit(prices: number[]): number {
  let r = 0;
  // mono stack, increase
  const stack: number[] = [];

  for (let price of prices) {
    while (stack.length > 0 && stack[stack.length - 1] > price) {
      stack.pop();
    }

    if (stack.length) {
      r = Math.max(r, price - stack[0]);
    }

    stack.push(price);
  }

  return r;
}

