  const table: { [key: number]: string } = {};
  for (let i = 0; i < listScore.length; i++) {
    table[listScore[i]] = String(i + 1);

    if (i === 0) {
      table[listScore[i]] = FIRST;
    }
    if (i === 1) {
      table[listScore[i]] = SECOND;
    }
    if (i === 2) {
      table[listScore[i]] = THIRD;
