  const listDup = [];

  for (let x = 0; x < s.length; x++) {
    let start = x;
    let next = x + 1;
    const current = s[x];

    while (current === s[next]) {
      next++;

      x = next - 1;
    }

    if (next - start >= 2) {
      listDup.push(s.slice(start, next));
    }
  }

  return listDup.length;
};

