export function moveZeroes(nums: number[]) {
  let left = 0;
  let right = 1;

  // [0,1,0,3,12]
  while (left < nums.length && right < nums.length) {
    const leftN = nums[left];
    const rightN = nums[right];

    if (leftN) {
      left++;
      right = left + 1;
    } else if (rightN === 0) {
      right++;
    } else {
      nums[left] = rightN;
      nums[right] = leftN;
      left++;
      right++;
    }
  }

  return nums;
}

