// Output: [3,4,6,16,17]

// Constraints:

// 1 <= nums.length <= 1000
// -10^6 <= nums[i] <= 10^6
var runningSum = function (nums: number[]) {
  let result: number[] = [];

  for (let x = 0; x < nums.length; x++) {
