  if (!mice.length) return;

  const miceSorted = mice.sort((a, b) => a - b);
  const holesSorted = holes.sort((a, b) => a - b);

  let maximum = 0;

  for (let x = 0; x < miceSorted.length; x++) {
    const steps = Math.abs(miceSorted[x] - holesSorted[x]);
